import pytest

from bedrock_protocol import v1001, v2168

VERSIONS = {"v1001": v1001, "v2168": v2168}

# generated by gophertunnel b8bd735:
# &packet.ItemRegistry{Items: []protocol.ItemEntry{{Name: "minecraft:stick", RuntimeID: 320, ComponentBased: false,
# Version: 0}, {Name: "custom:widget", RuntimeID: -1, ComponentBased: true, Version: 1,
# Data: map[string]any{"minecraft:max_stack_size": int32(16)}}}}
ITEMS = bytes.fromhex(
    "020f6d696e6563726166743a737469636b400100000a00000d637573746f6d3a776964676574ffff01020a0003186d696e65637261"
    "66743a6d61785f737461636b5f73697a652000"
)

# generated by gophertunnel b8bd735:
# &packet.ItemRegistry{}
EMPTY = bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        version.ItemRegistryPacket(
            items=[
                version.ItemData(
                    name="minecraft:stick",
                    id=320,
                    is_component_based=False,
                    item_version=version.ItemVersion.LEGACY,
                ),
                version.ItemData(
                    name="custom:widget",
                    id=-1,
                    is_component_based=True,
                    item_version=version.ItemVersion.DATA_DRIVEN,
                    component_data=version.nbt.CompoundTag({"minecraft:max_stack_size": version.nbt.IntTag(16)}),
                ),
            ]
        ),
        ITEMS,
        id=f"{name}-two-items",
    )
    for name, version in VERSIONS.items()
] + [
    pytest.param(version.ItemRegistryPacket(items=[]), EMPTY, id=f"{name}-empty") for name, version in VERSIONS.items()
]


@pytest.mark.parametrize("version", VERSIONS.values(), ids=VERSIONS.keys())
def test_item_registry_is_packet_162(version):
    assert version.PACKETS[162] is version.ItemRegistryPacket


def test_item_registry_is_one_type_across_the_two_eras():
    assert v1001.ItemRegistryPacket is v2168.ItemRegistryPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_item_registry_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_item_registry_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_a_negative_item_id_takes_a_fixed_two_bytes():
    assert ITEMS[38:40] == bytes.fromhex("ffff")
